CREATE TABLE IF NOT EXISTS document_vendor_identity_links (
  id INTEGER PRIMARY KEY,
  company_id INTEGER NOT NULL REFERENCES companies(id),
  document_id INTEGER NOT NULL REFERENCES documents(id),
  vendor_id INTEGER REFERENCES vendors(id),
  supplier_identity TEXT NOT NULL CHECK(length(trim(supplier_identity)) BETWEEN 1 AND 256),
  provenance TEXT NOT NULL CHECK(length(trim(provenance)) BETWEEN 1 AND 256),
  rationale TEXT NOT NULL CHECK(length(trim(rationale)) BETWEEN 1 AND 2000),
  created_by TEXT NOT NULL CHECK(length(trim(created_by)) BETWEEN 1 AND 256),
  created_at TEXT NOT NULL,
  UNIQUE(company_id, document_id)
);
CREATE INDEX IF NOT EXISTS idx_document_vendor_identity_links_company_identity ON document_vendor_identity_links(company_id, supplier_identity);
CREATE TABLE IF NOT EXISTS posting_rule_versions (
  id INTEGER PRIMARY KEY,
  rule_id TEXT NOT NULL CHECK(length(trim(rule_id)) BETWEEN 1 AND 128),
  company_id INTEGER NOT NULL REFERENCES companies(id),
  version INTEGER NOT NULL CHECK(version > 0),
  effective_from TEXT NOT NULL,
  effective_to TEXT,
  conditions_json TEXT NOT NULL,
  outcome_json TEXT NOT NULL,
  provenance TEXT NOT NULL CHECK(length(trim(provenance)) BETWEEN 1 AND 256),
  rationale TEXT NOT NULL CHECK(length(trim(rationale)) BETWEEN 1 AND 2000),
  created_by TEXT NOT NULL CHECK(length(trim(created_by)) BETWEEN 1 AND 256),
  payload_hash TEXT NOT NULL CHECK(length(payload_hash) = 64),
  created_at TEXT NOT NULL,
  UNIQUE(company_id, rule_id, version),
  UNIQUE(company_id, rule_id, payload_hash)
);
CREATE INDEX IF NOT EXISTS idx_posting_rule_versions_company_rule ON posting_rule_versions(company_id, rule_id, version);
CREATE TABLE IF NOT EXISTS posting_rule_lifecycle_events (
  id INTEGER PRIMARY KEY,
  rule_version_id INTEGER NOT NULL REFERENCES posting_rule_versions(id),
  state TEXT NOT NULL CHECK(state IN ('proposed','approved','rejected','disabled','superseded')),
  effective_at TEXT NOT NULL,
  actor TEXT NOT NULL CHECK(length(trim(actor)) BETWEEN 1 AND 256),
  approver TEXT,
  rationale TEXT NOT NULL CHECK(length(trim(rationale)) BETWEEN 1 AND 2000),
  provenance TEXT NOT NULL CHECK(length(trim(provenance)) BETWEEN 1 AND 256),
  expected_payload_hash TEXT NOT NULL CHECK(length(expected_payload_hash) = 64),
  superseding_version_id INTEGER REFERENCES posting_rule_versions(id),
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_posting_rule_lifecycle_version ON posting_rule_lifecycle_events(rule_version_id, effective_at, id);
CREATE TABLE IF NOT EXISTS posting_rule_applications (
  id INTEGER PRIMARY KEY,
  application_key TEXT NOT NULL UNIQUE,
  company_id INTEGER NOT NULL REFERENCES companies(id),
  document_id INTEGER REFERENCES documents(id),
  rule_version_id INTEGER REFERENCES posting_rule_versions(id),
  rule_payload_hash TEXT,
  decision TEXT NOT NULL CHECK(decision IN ('proposed','human_decision')),
  explanation_json TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_posting_rule_applications_company_document ON posting_rule_applications(company_id, document_id);
CREATE TRIGGER document_vendor_identity_links_no_update BEFORE UPDATE ON document_vendor_identity_links BEGIN SELECT RAISE(ABORT, 'document vendor identity links are append-only'); END;
CREATE TRIGGER document_vendor_identity_links_no_delete BEFORE DELETE ON document_vendor_identity_links BEGIN SELECT RAISE(ABORT, 'document vendor identity links are append-only'); END;
CREATE TRIGGER posting_rule_versions_no_update BEFORE UPDATE ON posting_rule_versions BEGIN SELECT RAISE(ABORT, 'posting rule versions are immutable'); END;
CREATE TRIGGER posting_rule_versions_no_delete BEFORE DELETE ON posting_rule_versions BEGIN SELECT RAISE(ABORT, 'posting rule versions are immutable'); END;
CREATE TRIGGER posting_rule_lifecycle_events_no_update BEFORE UPDATE ON posting_rule_lifecycle_events BEGIN SELECT RAISE(ABORT, 'posting rule lifecycle events are append-only'); END;
CREATE TRIGGER posting_rule_lifecycle_events_no_delete BEFORE DELETE ON posting_rule_lifecycle_events BEGIN SELECT RAISE(ABORT, 'posting rule lifecycle events are append-only'); END;
CREATE TRIGGER posting_rule_applications_no_update BEFORE UPDATE ON posting_rule_applications BEGIN SELECT RAISE(ABORT, 'posting rule applications are immutable'); END;
CREATE TRIGGER posting_rule_applications_no_delete BEFORE DELETE ON posting_rule_applications BEGIN SELECT RAISE(ABORT, 'posting rule applications are immutable'); END;
